begin;
select plan(3);
select has_function('public'::name, 'assign_enrollment_to_class'::name);
set local role authenticated;
set local request.jwt.claim.sub = '00000000-0000-0000-0000-000000000061';
select is(public.assign_enrollment_to_class('80000000-0000-0000-0000-000000000061', '60000000-0000-0000-0000-000000000061'), '80000000-0000-0000-0000-000000000061'::uuid, 'manager assigns matching class');
select throws_ok($$select public.assign_enrollment_to_class('80000000-0000-0000-0000-000000000061', '60000000-0000-0000-0000-000000000062')$$, 'CLASS_SCOPE_INVALID', 'different offering class is rejected');
select * from finish();
rollback;
